// Copies the physics demo documents generated by the MML fork (Frostyz44/mml-test, see its CLAUDE.md) into this
// world, adjusting them for the world's renderer: the fork's demos are lit for its plain viewers, and their lamps wash
// out the floors under this world's tone mapping, so their intensities are lowered here.
//
// Usage (from the repository root, after `npm run build-demo -w @mml-io/mml-physics` in the fork):
//   node scripts/import-physics-demos.mjs [path-to-fork]   (default: ../upstream-mml)
import fs from "node:fs";
import path from "node:path";

const repoRoot = path.resolve(path.dirname(new URL(import.meta.url).pathname.replace(/^\/([A-Za-z]:)/, "$1")), "..");
const forkRoot = path.resolve(repoRoot, process.argv[2] ?? "../upstream-mml");
const documents = path.join(repoRoot, "example/multi-user-3d-web-experience/server/mml-documents");

// Fork demo -> world document, and lamp intensities (candela) to replace
const imports = [
  { from: "demos/physics.html", to: "physics.html", intensities: { 900: 140, 300: 50 } },
  { from: "demos/ballpit.html", to: "ballpit.html", intensities: { 500: 90, 150: 40 } },
];

let problems = 0;
for (const { from, to, intensities } of imports) {
  const source = path.join(forkRoot, from);
  if (!fs.existsSync(source)) {
    console.error(`missing ${source}: build the fork's demos first`);
    problems++;
    continue;
  }
  let html = fs.readFileSync(source, "utf8");
  let replaced = 0;
  html = html.replace(/<m-light\b[^>]*>/g, (tag) =>
    tag.replace(/\bintensity="(\d+(?:\.\d+)?)"/, (attribute, value) => {
      const lowered = intensities[value];
      if (lowered === undefined) {
        return attribute;
      }
      replaced++;
      return `intensity="${lowered}"`;
    }),
  );
  fs.writeFileSync(path.join(documents, to), html);
  console.log(`${to} <- ${from} (${replaced} lamp${replaced === 1 ? "" : "s"} adjusted)`);
}
process.exit(problems ? 1 : 0);
